1  merge_with_prev (
     2    FriBidiRun *second
     3  )
     4  {
     5    FriBidiRun *first;
     6
     7    fribidi_assert (second);
     8    fribidi_assert (second->next);
     9    first = second->prev;
    10    fribidi_assert (first);
    11
    12    first->next = second->next;
    13    first->next->prev = first;
    14    RL_LEN (first) += RL_LEN (second);
    15    if (second->next_isolate)
    16      second->next_isolate->prev_isolate = second->prev_isolate;
    17    /* The following edge case typically shouldn't happen, but fuzz
    18       testing shows it does, and the assignment protects against
    19       a dangling pointer. */
    20    else if (second->next->prev_isolate == second)
    21      second->next->prev_isolate = second->prev_isolate;
    22    if (second->prev_isolate)
    23      second->prev_isolate->next_isolate = second->next_isolate;
    24    first->next_isolate = second->next_isolate;
    25
    26    fribidi_free (second);
    27    return first;
    28  }
    29  static void
    30  compact_list (
    31    FriBidiRun *list
    32  )
    33  {
    34    fribidi_assert (list);
    35
    36    if (list->next)
    37      for_run_list (list, list)
    38        if (RL_TYPE (list->prev) == RL_TYPE (list)
    39            && RL_LEVEL (list->prev) == RL_LEVEL (list)
    40            && RL_BRACKET_TYPE(list) == FRIBIDI_NO_BRACKET /* Don't join brackets! */
    41            && RL_BRACKET_TYPE(list->prev) == FRIBIDI_NO_BRACKET
    42            )
    43        list = merge_with_prev (list);
    44  }
